+	unsigned long		work_flags;
+	struct work_struct	work;
+
+	unsigned long misc_flags;
+	unsigned long md_flags;
+	enum devcoredump_state md_state;
+	struct btqcom_memdump md;
+	struct qbtc_subsys_data subsys[QBTC_SUBSYS_MAX];
+};
